for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	vis = set()
	ans = 0
	for i in range(30, -1, -1):
		f = 1
		h = []
		for j in range(n):
			if j in vis:
				if 1 << i & b[j] == 0:
					f = 0
			elif a[j] & 1 << i == 0:
				if b[j] & 1 << i and b[j] & ans == ans:
					h.append(j)
				else:
					f = 0
		if f:
			ans += 1 << i
			for j in h:
				vis.add(j)
	print(ans, len(vis))
